/* ── Reset & Base ─────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:        #f7f7f5;
  --clr-surface:   #ffffff;
  --clr-border:    #e8e8e4;
  --clr-text:      #1a1a1a;
  --clr-muted:     #6b6b6b;
  --clr-accent:    #c84b31;
  --clr-accent-dk: #a33a23;
  --clr-badge:     #f0e6c8;
  --clr-badge-txt: #7a5c1e;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-sm:     0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:     0 4px 16px rgba(0,0,0,.08);
  --shadow-lg:     0 12px 40px rgba(0,0,0,.12);
  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
  --transition:    200ms ease;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font-sans); background: var(--clr-bg); color: var(--clr-text); line-height: 1.6; -webkit-font-smoothing: antialiased; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ── Layout helpers ───────────────────────────────────── */
.container { max-width: 1200px; margin-inline: auto; padding-inline: 24px; }
.section-gap { padding-block: 72px; }

/* ── Typography ───────────────────────────────────────── */
.section-label {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: .75rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase;
  color: var(--clr-accent); margin-bottom: 12px;
}
.section-label::before { content: ''; width: 24px; height: 2px; background: var(--clr-accent); border-radius: 2px; }
.section-title { font-size: clamp(1.5rem, 2.5vw, 2rem); font-weight: 700; letter-spacing: -.03em; line-height: 1.2; }
.section-subtitle { color: var(--clr-muted); margin-top: 8px; font-size: .95rem; }

/* ── Buttons ──────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: 8px; padding: 12px 24px;
  border-radius: var(--radius-md); font-size: .9rem; font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:active { transform: scale(.97); }
.btn-primary { background: var(--clr-text); color: #fff; }
.btn-primary:hover { background: #333; box-shadow: var(--shadow-md); }
.btn-accent { background: var(--clr-accent); color: #fff; }
.btn-accent:hover { background: var(--clr-accent-dk); box-shadow: var(--shadow-md); }
.btn-outline { border: 1.5px solid var(--clr-border); color: var(--clr-text); background: var(--clr-surface); }
.btn-outline:hover { border-color: var(--clr-text); background: var(--clr-text); color: #fff; }
.btn-ghost { color: var(--clr-text); padding: 10px 16px; border-radius: var(--radius-sm); }
.btn-ghost:hover { background: var(--clr-border); }
.btn-icon { width: 40px; height: 40px; padding: 0; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; }

/* ── Header / Nav ─────────────────────────────────────── */
#header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(247,247,245,.88); backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--clr-border);
}
.nav-inner {
  display: flex; align-items: center; height: 64px; gap: 32px;
}
.nav-logo { font-size: 1.25rem; font-weight: 800; letter-spacing: -.04em; flex-shrink: 0; }
.nav-logo span { color: var(--clr-accent); }
.nav-links { display: flex; gap: 4px; flex: 1; }
.nav-links a {
  padding: 8px 12px; border-radius: var(--radius-sm); font-size: .88rem; font-weight: 500;
  color: var(--clr-muted); transition: color var(--transition), background var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--clr-text); background: var(--clr-border); }
.nav-actions { display: flex; align-items: center; gap: 4px; }
.nav-actions .cart-btn { position: relative; }
.cart-count {
  position: absolute; top: -4px; right: -4px; width: 18px; height: 18px;
  background: var(--clr-accent); color: #fff; font-size: .65rem; font-weight: 700;
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
}
.nav-search-wrap { position: relative; }
.nav-search-wrap input {
  width: 220px; padding: 8px 12px 8px 36px;
  border: 1.5px solid var(--clr-border); border-radius: var(--radius-md);
  background: var(--clr-surface); font-size: .88rem; font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}
.nav-search-wrap input:focus { border-color: var(--clr-text); box-shadow: 0 0 0 3px rgba(26,26,26,.06); }
.nav-search-icon { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: var(--clr-muted); pointer-events: none; }

/* ── Announcement bar ─────────────────────────────────── */
.announcement-bar {
  background: var(--clr-text); color: #fff; text-align: center;
  padding: 9px; font-size: .8rem; font-weight: 500; letter-spacing: .04em;
}
.announcement-bar a { text-decoration: underline; opacity: .8; }

/* ── Hero ─────────────────────────────────────────────── */
#hero {
  background: var(--clr-surface); overflow: hidden;
  min-height: 540px; display: flex; align-items: stretch;
}
.hero-inner {
  display: grid; grid-template-columns: 1fr 1fr; min-height: 540px;
}
.hero-content {
  display: flex; flex-direction: column; justify-content: center;
  padding: 64px 48px 64px 0; gap: 24px;
}
.hero-badge {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--clr-badge); color: var(--clr-badge-txt);
  padding: 5px 12px; border-radius: 99px; font-size: .78rem; font-weight: 600;
  width: fit-content;
}
.hero-title {
  font-size: clamp(2.2rem, 5vw, 3.5rem); font-weight: 800;
  letter-spacing: -.04em; line-height: 1.08;
}
.hero-title em { font-style: normal; color: var(--clr-accent); }
.hero-desc { color: var(--clr-muted); max-width: 420px; font-size: 1rem; line-height: 1.7; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-stats { display: flex; gap: 32px; padding-top: 16px; border-top: 1px solid var(--clr-border); }
.hero-stat-num { font-size: 1.5rem; font-weight: 800; letter-spacing: -.03em; }
.hero-stat-lbl { font-size: .78rem; color: var(--clr-muted); margin-top: 2px; }
.hero-visual {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, #f0ebe3 0%, #e8e0d4 100%);
  border-radius: 0 0 0 var(--radius-lg);
}
.hero-visual-img {
  width: 100%; height: 100%; object-fit: cover; object-position: center top;
  transition: transform .6s ease;
}
.hero-visual:hover .hero-visual-img { transform: scale(1.03); }
.hero-visual-tag {
  position: absolute; bottom: 28px; left: 28px;
  background: rgba(255,255,255,.92); backdrop-filter: blur(8px);
  border-radius: var(--radius-md); padding: 14px 18px;
  box-shadow: var(--shadow-md); display: flex; align-items: center; gap: 14px;
}
.hero-visual-tag-txt { font-size: .8rem; color: var(--clr-muted); }
.hero-visual-tag-name { font-size: .95rem; font-weight: 700; margin-top: 2px; }
.hero-visual-tag-price { font-size: 1.1rem; font-weight: 800; color: var(--clr-accent); }

/* ── Category chips ───────────────────────────────────── */
#categories { padding-block: 36px; }
.category-list { display: flex; gap: 12px; overflow-x: auto; scrollbar-width: none; padding-bottom: 4px; }
.category-list::-webkit-scrollbar { display: none; }
.category-chip {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  padding: 18px 24px; border-radius: var(--radius-md);
  background: var(--clr-surface); border: 1.5px solid var(--clr-border);
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  flex-shrink: 0; cursor: pointer;
}
.category-chip:hover { border-color: var(--clr-text); box-shadow: var(--shadow-sm); transform: translateY(-2px); }
.category-chip.active { border-color: var(--clr-text); background: var(--clr-text); color: #fff; }
.category-icon { font-size: 1.6rem; }
.category-name { font-size: .8rem; font-weight: 600; white-space: nowrap; }

/* ── Product cards ────────────────────────────────────── */
.products-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 32px; }
.products-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }

.product-card {
  background: var(--clr-surface); border-radius: var(--radius-md);
  border: 1.5px solid var(--clr-border); overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex; flex-direction: column;
}
.product-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.product-img-wrap { position: relative; overflow: hidden; aspect-ratio: 3/4; background: #f0ede8; }
.product-img-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
.product-card:hover .product-img-wrap img { transform: scale(1.05); }
.product-badge {
  position: absolute; top: 12px; left: 12px;
  background: var(--clr-accent); color: #fff;
  padding: 3px 9px; border-radius: 99px; font-size: .7rem; font-weight: 700;
}
.product-badge.new { background: var(--clr-text); }
.product-badge.bestseller { background: #2d7a4f; }
.product-actions {
  position: absolute; top: 12px; right: 12px; display: flex; flex-direction: column; gap: 6px;
  opacity: 0; transform: translateX(8px); transition: opacity var(--transition), transform var(--transition);
}
.product-card:hover .product-actions { opacity: 1; transform: translateX(0); }
.product-action-btn {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,.92); backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-sm); font-size: 1rem;
  transition: background var(--transition);
}
.product-action-btn:hover { background: #fff; }
.product-info { padding: 16px; flex: 1; display: flex; flex-direction: column; gap: 6px; }
.product-category { font-size: .72rem; text-transform: uppercase; letter-spacing: .08em; color: var(--clr-muted); font-weight: 600; }
.product-name { font-size: .95rem; font-weight: 700; line-height: 1.3; }
.product-rating { display: flex; align-items: center; gap: 4px; }
.stars { color: #f5a623; font-size: .82rem; letter-spacing: 1px; }
.rating-count { font-size: .75rem; color: var(--clr-muted); }
.product-footer { display: flex; align-items: center; justify-content: space-between; margin-top: auto; padding-top: 12px; }
.product-price { font-size: 1.05rem; font-weight: 800; }
.product-price-orig { font-size: .85rem; color: var(--clr-muted); text-decoration: line-through; margin-left: 4px; font-weight: 400; }
.add-to-cart {
  width: 34px; height: 34px; border-radius: 50%;
  background: var(--clr-text); color: #fff; font-size: 1.1rem;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.add-to-cart:hover { background: var(--clr-accent); transform: scale(1.1); }

/* ── Deals section ────────────────────────────────────── */
#deals { background: var(--clr-surface); border-block: 1px solid var(--clr-border); }
.deals-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; align-items: start; }
.deals-main-card {
  border-radius: var(--radius-lg); overflow: hidden; position: relative;
  background: linear-gradient(145deg, #1a1a1a 0%, #2d2d2d 100%);
  color: #fff; min-height: 420px; display: flex; flex-direction: column; justify-content: flex-end;
  padding: 36px;
}
.deals-main-bg {
  position: absolute; inset: 0; object-fit: cover; opacity: .35;
  width: 100%; height: 100%;
}
.deals-main-content { position: relative; z-index: 1; }
.deals-main-label { font-size: .72rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: #f5a623; margin-bottom: 10px; }
.deals-main-title { font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 800; letter-spacing: -.03em; line-height: 1.15; }
.deals-main-desc { color: rgba(255,255,255,.7); margin-top: 10px; font-size: .9rem; line-height: 1.6; }
.deals-main-cta { display: flex; align-items: center; gap: 16px; margin-top: 24px; }
.deals-main-price { font-size: 2rem; font-weight: 900; letter-spacing: -.04em; }
.deals-main-price span { font-size: 1rem; font-weight: 400; color: rgba(255,255,255,.6); text-decoration: line-through; margin-left: 8px; }

.countdown { display: flex; gap: 10px; margin-top: 20px; }
.countdown-unit {
  background: rgba(255,255,255,.12); border-radius: var(--radius-sm);
  padding: 10px 14px; text-align: center; min-width: 58px;
}
.countdown-num { font-size: 1.5rem; font-weight: 800; line-height: 1; display: block; }
.countdown-label { font-size: .65rem; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.6); margin-top: 4px; display: block; }

.deals-stack { display: flex; flex-direction: column; gap: 16px; }
.deal-card {
  display: flex; gap: 16px; align-items: center;
  background: var(--clr-bg); border-radius: var(--radius-md);
  border: 1.5px solid var(--clr-border); padding: 16px;
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}
.deal-card:hover { box-shadow: var(--shadow-md); transform: translateX(4px); }
.deal-img { width: 84px; height: 84px; border-radius: var(--radius-sm); object-fit: cover; flex-shrink: 0; background: #e8e4de; }
.deal-info { flex: 1; min-width: 0; }
.deal-cat { font-size: .72rem; font-weight: 600; text-transform: uppercase; letter-spacing: .07em; color: var(--clr-muted); }
.deal-name { font-size: .95rem; font-weight: 700; margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deal-prices { display: flex; align-items: baseline; gap: 8px; margin-top: 6px; }
.deal-price-new { font-size: 1.05rem; font-weight: 800; color: var(--clr-accent); }
.deal-price-old { font-size: .83rem; color: var(--clr-muted); text-decoration: line-through; }
.deal-pct { font-size: .72rem; font-weight: 700; background: var(--clr-accent); color: #fff; padding: 2px 7px; border-radius: 99px; }
.deal-progress-wrap { margin-top: 8px; }
.deal-progress-bar { height: 4px; background: var(--clr-border); border-radius: 99px; overflow: hidden; }
.deal-progress-fill { height: 100%; background: var(--clr-accent); border-radius: 99px; }
.deal-progress-txt { font-size: .7rem; color: var(--clr-muted); margin-top: 4px; }

/* ── Editorial ────────────────────────────────────────── */
.editorial-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.editorial-card {
  border-radius: var(--radius-md); overflow: hidden;
  background: var(--clr-surface); border: 1.5px solid var(--clr-border);
  display: flex; flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.editorial-card.featured { grid-column: span 2; flex-direction: row; }
.editorial-img-wrap { overflow: hidden; aspect-ratio: 16/9; flex-shrink: 0; }
.editorial-card.featured .editorial-img-wrap { flex: 1; aspect-ratio: auto; }
.editorial-img-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.editorial-card:hover .editorial-img-wrap img { transform: scale(1.04); }
.editorial-body { padding: 24px; display: flex; flex-direction: column; gap: 10px; justify-content: center; }
.editorial-tag {
  display: inline-flex; align-items: center; gap: 4px;
  background: var(--clr-badge); color: var(--clr-badge-txt);
  padding: 3px 10px; border-radius: 99px; font-size: .72rem; font-weight: 700;
  width: fit-content;
}
.editorial-title { font-size: 1.05rem; font-weight: 700; line-height: 1.35; }
.editorial-card.featured .editorial-title { font-size: 1.3rem; }
.editorial-excerpt { font-size: .87rem; color: var(--clr-muted); line-height: 1.65; }
.editorial-meta { display: flex; align-items: center; gap: 10px; font-size: .78rem; color: var(--clr-muted); margin-top: 4px; }
.editorial-meta-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--clr-muted); }
.editorial-read-more { display: flex; align-items: center; gap: 6px; font-size: .85rem; font-weight: 600; color: var(--clr-text); margin-top: 4px; transition: gap var(--transition); width: fit-content; }
.editorial-card:hover .editorial-read-more { gap: 10px; }

/* ── Newsletter ───────────────────────────────────────── */
#newsletter {
  background: var(--clr-text); color: #fff; text-align: center; padding-block: 64px;
}
.newsletter-inner { max-width: 560px; margin-inline: auto; }
.newsletter-title { font-size: clamp(1.4rem, 3vw, 2rem); font-weight: 800; letter-spacing: -.03em; }
.newsletter-sub { color: rgba(255,255,255,.6); margin-top: 10px; }
.newsletter-form { display: flex; gap: 10px; margin-top: 28px; }
.newsletter-input {
  flex: 1; padding: 13px 18px; border-radius: var(--radius-md);
  border: 1.5px solid rgba(255,255,255,.15); background: rgba(255,255,255,.08);
  color: #fff; font-family: inherit; font-size: .9rem; outline: none;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input:focus { border-color: rgba(255,255,255,.4); }
.newsletter-disclaimer { margin-top: 14px; font-size: .75rem; color: rgba(255,255,255,.4); }

/* ── Footer ───────────────────────────────────────────── */
#footer { background: var(--clr-surface); border-top: 1px solid var(--clr-border); padding-block: 56px 32px; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; }
.footer-brand p { color: var(--clr-muted); font-size: .88rem; line-height: 1.7; margin-top: 12px; max-width: 260px; }
.footer-socials { display: flex; gap: 10px; margin-top: 20px; }
.social-btn {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--clr-bg); border: 1.5px solid var(--clr-border);
  display: flex; align-items: center; justify-content: center; font-size: .9rem;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
}
.social-btn:hover { background: var(--clr-text); border-color: var(--clr-text); color: #fff; transform: translateY(-2px); }
.footer-col h4 { font-size: .85rem; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; margin-bottom: 16px; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: .88rem; color: var(--clr-muted); transition: color var(--transition); }
.footer-col ul a:hover { color: var(--clr-text); }
.footer-bottom { border-top: 1px solid var(--clr-border); padding-top: 24px; margin-top: 48px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; }
.footer-bottom p { font-size: .8rem; color: var(--clr-muted); }
.footer-payments { display: flex; gap: 8px; }
.payment-badge {
  padding: 4px 10px; border-radius: var(--radius-sm); border: 1px solid var(--clr-border);
  font-size: .7rem; font-weight: 700; color: var(--clr-muted); background: var(--clr-bg);
}

/* ── Toast ────────────────────────────────────────────── */
#toast-container { position: fixed; bottom: 24px; right: 24px; z-index: 9999; display: flex; flex-direction: column; gap: 10px; }
.toast {
  background: var(--clr-text); color: #fff; padding: 14px 20px; border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg); display: flex; align-items: center; gap: 10px; font-size: .88rem; font-weight: 500;
  animation: toastIn .25s ease; max-width: 320px;
}
.toast.removing { animation: toastOut .25s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(12px) scale(.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(12px) scale(.95); } }

/* ── Responsive ───────────────────────────────────────── */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-search-wrap { display: none; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-content { padding: 40px 0; }
  .hero-visual { min-height: 300px; border-radius: var(--radius-lg) var(--radius-lg) 0 0; order: -1; }
  .deals-layout { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.featured { flex-direction: column; grid-column: auto; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .products-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
}

